        int m = l0; if (l1 < m) m = l1; if (l2 < m) m = l2; if (l3 < m) m = l3;
        for (int t = 0; t < m; t++) {
            s0 += data[a0 + t] * x[indices[a0 + t]];
            s1 += data[a1 + t] * x[indices[a1 + t]];
            s2 += data[a2 + t] * x[indices[a2 + t]];
