typedef void (*naupd_t)(void *st, double *resid, double *v, int ldv, int *ipntr, double *workd, double *workl);
#define B 8
/* ELL blocks: for block b (rows b*B..b*B+B-1), width w[b], data at off[b], layout [t][r] */
static inline void matvec(int n, int nb, const int *restrict off, const int *restrict w,
                          const int *restrict idx, const double *restrict val,
                          const double *restrict x, double *restrict y)
{
    for (int b = 0; b < nb; b++) {
        const int *ii = idx + off[b];
        const double *vv = val + off[b];
        double s[B];
        for (int r = 0; r < B; r++) s[r] = 0.0;
        int W = w[b];
        for (int t = 0; t < W; t++) {
            for (int r = 0; r < B; r++) s[r] += vv[t * B + r] * x[ii[t * B + r]];
        }
        int base = b * B;
        if (base + B <= n) { for (int r = 0; r < B; r++) y[base + r] = s[r]; }
        else { for (int r = 0; base + r < n; r++) y[base + r] = s[r]; }
    }
}

