import numpy as np
def build_ell(A, B=8):
    n = A.shape[0]
    indptr = A.indptr.astype(np.int64); lens = np.diff(indptr)
    nb = (n + B - 1) // B
    lp = np.zeros(nb * B, np.int64); lp[:n] = lens
    w = lp.reshape(nb, B).max(axis=1)
    off = np.zeros(nb, np.int64); off[1:] = np.cumsum(w * B)[:-1]
    total = int((w * B).sum())
    idx = np.zeros(total, np.int32); val = np.zeros(total, np.float64)
    rows = np.repeat(np.arange(n), lens)
    t = np.arange(A.nnz) - indptr[rows]
    b = rows // B; r = rows % B
    pos = off[b] + t * B + r
    idx[pos] = A.indices; val[pos] = A.data
    return nb, off.astype(np.int32), w.astype(np.int32), idx, val
