#include <stdint.h>
typedef void (*naupd_t)(void *st, double *resid, double *v, int ldv, int *ipntr, double *workd, double *workl);

/* CSR, 4 rows interleaved; per-row summation order is identical to scipy's csr_matvec */
static void mv_csr(int n, const int *restrict indptr, const int *restrict ind,
                   const double *restrict data, const double *restrict x, double *restrict y)
{
    int i = 0;
    for (; i + 4 <= n; i += 4) {
        int a0 = indptr[i], e0 = indptr[i+1], a1 = e0, e1 = indptr[i+2];
        int a2 = e1, e2 = indptr[i+3], a3 = e2, e3 = indptr[i+4];
        double s0 = 0, s1 = 0, s2 = 0, s3 = 0;
        int m = e0 - a0; if (e1 - a1 < m) m = e1 - a1; if (e2 - a2 < m) m = e2 - a2; if (e3 - a3 < m) m = e3 - a3;
        for (int t = 0; t < m; t++) {
            s0 += data[a0+t] * x[ind[a0+t]]; s1 += data[a1+t] * x[ind[a1+t]];
            s2 += data[a2+t] * x[ind[a2+t]]; s3 += data[a3+t] * x[ind[a3+t]];
        }
        for (int j = a0 + m; j < e0; j++) s0 += data[j] * x[ind[j]];
        for (int j = a1 + m; j < e1; j++) s1 += data[j] * x[ind[j]];
        for (int j = a2 + m; j < e2; j++) s2 += data[j] * x[ind[j]];
        for (int j = a3 + m; j < e3; j++) s3 += data[j] * x[ind[j]];
        y[i] = s0; y[i+1] = s1; y[i+2] = s2; y[i+3] = s3;
    }
    for (; i < n; i++) {
        double s = 0; for (int j = indptr[i]; j < indptr[i+1]; j++) s += data[j] * x[ind[j]]; y[i] = s;
    }
}

/* ELL blocks of 8 rows, uint16 column indices, layout [t][r]; padding entries are 0*x[0] = +0,
   which leaves the sums bit-identical (s + 0.0 == s for any finite s other than -0 -> +0). */
static void mv_ell(int n, int nb, const int *restrict off, const int *restrict w,
                   const uint16_t *restrict idx, const double *restrict val,
                   const double *restrict x, double *restrict y)
{
    for (int b = 0; b < nb; b++) {
        const uint16_t *ii = idx + off[b]; const double *vv = val + off[b];
        double s[8] = {0, 0, 0, 0, 0, 0, 0, 0}; int W = w[b];
        for (int t = 0; t < W; t++) for (int r = 0; r < 8; r++) s[r] += vv[8*t+r] * x[ii[8*t+r]];
        int base = 8 * b; for (int r = 0; r < 8 && base + r < n; r++) y[base+r] = s[r];
    }
}

int arn_loop(naupd_t f, void *st, double *resid, double *v, int n, int *ipntr,
             double *workd, double *workl, int mode,
             const int *p0, const int *p1, const void *p2, const double *p3, int nb)
{
    int *ido = (int *)((char *)st + 0x34);
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        int d = *ido;
        if (d == 1 || d == 5) {
            if (mode == 0) mv_csr(n, p0, (const int *)p2, p3, workd + ipntr[0], workd + ipntr[1]);
            else mv_ell(n, nb, p0, p1, (const uint16_t *)p2, p3, workd + ipntr[0], workd + ipntr[1]);
        } else return d;
    }
}
